   507  static bool parse_sigalg_pairs(Array<uint16_t> *out, const int *values,
   508                                 size_t num_values) {
   509    if ((num_values & 1) == 1) {
   510      return false;
   511    }
   512
   513    const size_t num_pairs = num_values / 2;
   514    if (!out->Init(num_pairs)) {
   515      return false;
   516    }
   517
   518    for (size_t i = 0; i < num_values; i += 2) {
   519      const int hash_nid = values[i];
   520      const int pkey_type = values[i+1];
   521
   522      bool found = false;
   523      for (const auto &candidate : kSignatureAlgorithmsMapping) {
   524        if (candidate.pkey_type == pkey_type && candidate.hash_nid == hash_nid) {
   525          (*out)[i / 2] = candidate.signature_algorithm;
   526          found = true;
   527          break;
   528        }
   529      }
   530
   531      if (!found) {
   532        OPENSSL_PUT_ERROR(SSL, SSL_R_INVALID_SIGNATURE_ALGORITHM);
   533        ERR_add_error_dataf("unknown hash:%d pkey:%d", hash_nid, pkey_type);
   534        return false;
   535      }
   536    }
   537
   538    return true;
   539  }
