   553  static bool sigalgs_unique(Span<const uint16_t> in_sigalgs) {
   554    Array<uint16_t> sigalgs;
   555    if (!sigalgs.CopyFrom(in_sigalgs)) {
   556      return false;
   557    }
   558
   559    qsort(sigalgs.data(), sigalgs.size(), sizeof(uint16_t), compare_uint16_t);
   560
   561    for (size_t i = 1; i < sigalgs.size(); i++) {
   562      if (sigalgs[i - 1] == sigalgs[i]) {
   563        OPENSSL_PUT_ERROR(SSL, SSL_R_DUPLICATE_SIGNATURE_ALGORITHM);
   564        return false;
   565      }
   566    }
   567
   568    return true;
   569  }
